use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

enum Mode {
    Suggest,
    Syntax,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut files = Vec::new();
    let mut mode = Mode::SyntaxSuggest;
    let mut stop_parsing_options = false;

    for arg in args.iter().skip(1) {
        if stop_parsing_options {
            files.push(arg.clone());
            continue;
        }

        match arg.as_str() {
            "--suggest" => mode = Mode::Suggest,
            "--syntax" => mode = Mode::Syntax,
            "--syntax-suggest" => mode = Mode::SyntaxSuggest,
            "--transform" => mode = Mode::Transform,
            "--check" => mode = Mode::Check,
            "--replace" => mode = Mode::Replace,
            "--" => stop_parsing_options = true,
            "-h" | "--help" => {
                print_help();
                return;
            }
            "--version" => {
                println!("4.3.1");
                return;
            }
            _ if arg.starts_with('-') => {
                eprintln!("{}: No such option.", arg);
                process::exit(3);
            }
            _ => files.push(arg.clone()),
        }
    }

    if files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        if io::stdin().read_to_string(&mut input).is_ok() {
            process_input(&input, &mode, None);
        }
    } else {
        let mut any_changes = false;
        for file in files {
            if file == "" {
                let mut input = String::new();
                if io::stdin().read_to_string(&mut input).is_ok() {
                    process_input(&input, &mode, None);
                }
                continue;
            }
            let input = match fs::read_to_string(&file) {
                Ok(content) => content,
                Err(e) => {
                    eprintln!("{}: {}", file, e);
                    process::exit(1);
                }
            };
            if let Mode::Replace = mode {
                let (output, changed) = transform(&input);
                if changed {
                    fs::write(&file, output).unwrap();
                    any_changes = true;
                }
            } else {
                let changed = process_input(&input, &mode, Some(&file));
                if changed {
                    any_changes = true;
                }
            }
        }
        if let Mode::Check = mode {
            if any_changes {
                process::exit(2);
            } else {
                process::exit(0);
            }
        }
    }
}

fn print_help() {
    println!("Shellharden: The corrective bash syntax highlighter.");
    println!("");
    println!("Usage:");
    println!("\tshellharden [options] [files]");
    println!("\tcat files | shellharden [options] ''");
    println!("");
    println!("Shellharden is a syntax highlighter and a tool to semi-automate the rewriting");
    println!("of scripts to ShellCheck conformance, mainly focused on quoting.");
    println!("");
    println!("The default mode of operation is like `cat`, but with syntax highlighting in");
    println!("foreground colors and suggestive changes in background colors.");
    println!("");
    println!("Options:");
    println!("\t--suggest         Output a colored diff suggesting changes.");
    println!("\t--syntax          Output syntax highlighting with ANSI colors.");
    println!("\t--syntax-suggest  Diff with syntax highlighting (default mode).");
    println!("\t--transform       Output suggested changes.");
    println!("\t--check           No output; exit with 2 if changes are suggested.");
    println!("\t--replace         Replace file contents with suggested changes.");
    println!("\t--                Don't treat further arguments as options.");
    println!("\t-h|--help         Show help text.");
    println!("\t--version         Show version.");
    println!("");
    println!("The changes suggested by Shellharden inhibits word splitting and indirect");
    println!("pathname expansion. This will make your script ShellCheck compliant in terms of");
    println!("quoting. Whether your script will work afterwards is a different question:");
    println!("If your script was using those features on purpose, it obviously won't anymore!");
    println!("");
    println!("Every script is possible to write without using word splitting or indirect");
    println!("pathname expansion, but it may involve doing things differently.");
    println!("See the accompanying file how_to_do_things_safely_in_bash.md or online:");
    println!("https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md");
}

fn transform(input: &str) -> (String, bool) {
    // Placeholder for transformation logic
    (input.to_string(), false)
}

fn process_input(input: &str, mode: &Mode, filename: Option<&str>) -> bool {
    // Placeholder for processing logic
    match mode {
        Mode::Transform => {
            let (output, changed) = transform(input);
            print!("{}", output);
            changed
        }
        Mode::Check => {
            let (_, changed) = transform(input);
            changed
        }
        _ => {
            // Placeholder for highlighting and suggesting
            print!("{}", input);
            false
        }
    }
}
