    let mut i = 0;
    let chars: Vec<char> = input.chars().collect();
    while i < chars.len() {
        if chars[i] == '$' && i + 1 < chars.len() && chars[i+1].is_alphabetic() {
            output.push('"');
            output.push('$');
            i += 1;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                output.push(chars[i]);
                i += 1;
            }
            output.push('"');
            changed = true;
        } else {
            output.push(chars[i]);
            i += 1;
        }
    }
    (output, changed)
}

