fn is_safe_var(name: &str) -> bool {
    matches!(name, "?" | "$" | "!" | "#") || name.starts_with('#')
}

fn is_keyword(text: &str) -> bool {
    matches!(text, "if" | "then" | "elif" | "else" | "fi" | "for" | "in" | "do" | "done" | "case" | "esac" | "while" | "until" | "local" | "function")
}

fn is_command_likely(pos: usize, chars: &[char]) -> bool {
    if pos == 0 { return true; }
    let mut j = pos;
    while j > 0 {
        j -= 1;
        if chars[j] == '\n' || chars[j] == ';' || chars[j] == '|' || chars[j] == '&' { return true; }
        if !chars[j].is_whitespace() { return false; }
    }
